// Nullable enabled, warnings as errors. A string? here is a decision, not
// an accident, and the compiler enforces every check.
#nullable enable

public abstract record RefundResult
{
    public sealed record Refunded(string Reference, long AmountMinor) : RefundResult;
    public sealed record Rejected(string Code, bool Retryable) : RefundResult;
    public sealed record AlreadyRefunded(string Reference) : RefundResult;

    private RefundResult() { }   // closed: no outside implementations
}

public sealed class RefundService(HttpClient http, ILogger<RefundService> log)
{
    public async Task<RefundResult> RefundAsync(
        string paymentId,
        long amountMinor,
        CancellationToken ct)      // threaded, not accepted and ignored
    {
        using var response = await http.PostAsJsonAsync(
            $"payments/{paymentId}/refunds",
            new { amountMinor },
            ct);

        if (response.StatusCode == HttpStatusCode.Conflict)
        {
            var existing = await response.Content.ReadFromJsonAsync<ExistingRefund>(ct);
            // existing may be null; the compiler insists we say what happens.
            return existing is null
                ? new RefundResult.Rejected("MALFORMED_CONFLICT", Retryable: false)
                : new RefundResult.AlreadyRefunded(existing.Reference);
        }

        var body = await response.Content.ReadFromJsonAsync<RefundBody>(ct)
            ?? throw new InvalidOperationException("Empty refund response");

        return new RefundResult.Refunded(body.Reference, body.AmountMinor);
    }
}

// No default arm. A fourth outcome breaks this build rather than silently
// falling through to a message nobody wrote.
public static string Describe(RefundResult result) => result switch
{
    RefundResult.Refunded(var reference, var amount) => $"Refunded {amount} ({reference})",
    RefundResult.Rejected(var code, true)            => $"Rejected ({code}) - will retry",
    RefundResult.Rejected(var code, false)           => $"Rejected ({code}) - manual review",
    RefundResult.AlreadyRefunded(var reference)      => $"Already refunded ({reference})",
};
